begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('86000000-0000-4000-8000-000000000001','voucher-venues-admin@example.invalid'),('86000000-0000-4000-8000-000000000002','voucher-venues-td@example.invalid');
insert into public.profiles(id,full_name,role) values ('86000000-0000-4000-8000-000000000001','Venue admin','admin'),('86000000-0000-4000-8000-000000000002','TD staff','player') on conflict(id) do update set role=excluded.role;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select gen_random_uuid(),id,'totp','verified','LOCAL-TEST-ONLY',now(),now() from auth.users where id in ('86000000-0000-4000-8000-000000000001','86000000-0000-4000-8000-000000000002');
insert into public.staff_employee_profiles(profile_id,legal_name,department,active) values ('86000000-0000-4000-8000-000000000002','TD staff','VRena',true);
insert into public.staff_employee_locations values ('86000000-0000-4000-8000-000000000002','cafe-des-stagiaires');
insert into auth.users(id,email) select '86000000-0000-4000-8000-000000000003','contact@vre-vietnam.com' where not exists(select 1 from auth.users where email='contact@vre-vietnam.com');
insert into public.profiles(id,full_name,role) select id,'Shared test login','player' from auth.users where email='contact@vre-vietnam.com' on conflict(id) do nothing;
update public.staff_employee_profiles set kiosk_access_role='staff' where profile_id='86000000-0000-4000-8000-000000000002';
insert into private.staff_kiosk_pin_credentials(profile_id,pin_hash,access_role) values('86000000-0000-4000-8000-000000000002','TEST ONLY','staff');
insert into private.staff_kiosk_operator_sessions(auth_user_id,operator_profile_id,access_role,token_hash) select id,'86000000-0000-4000-8000-000000000002','staff',encode(extensions.digest('multi-venue-td-token','sha256'),'hex') from auth.users where email='contact@vre-vietnam.com';
select set_config('test.venue_staff_login',(select id::text from auth.users where email='contact@vre-vietnam.com'),true);

insert into public.staff_orders(id,order_number,booking_date,booking_time,players_count,total,subtotal,arena_id,payment_status,order_status,payment_method) values
 ('86000000-0000-4000-8000-000000000011','VENUE-VOUCHER-SOURCE',current_date,'10:00',1,300000,300000,'arena-1','paid','completed','cash'),
 ('86000000-0000-4000-8000-000000000012','VENUE-VOUCHER-TD',current_date,'10:00',1,50000,50000,'cafe:arena-1','unpaid','confirmed','unpaid');
select ok(not has_function_privilege('anon','public.staff_convert_payment_to_voucher(uuid,uuid,uuid,integer,text,integer,text[])','execute'),'Anonymous cannot select issuance venues');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"86000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
set local role authenticated;
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,gen_random_uuid(),100000,'Empty venues',30,array[]::text[])$q$,'P0001','Select at least one active venue.','Empty selection rejected');
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,gen_random_uuid(),100000,'Unknown venue',30,array['unknown'])$q$,'P0001','Select at least one active venue.','Unknown venue rejected');
select lives_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,'86000000-0000-4000-8000-000000000021',100000,'Both venues',90,array['ha-do-centrosa','cafe-des-stagiaires'])$q$,'Issue one voucher for both venues');
select is((select venue_key from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),'ha-do-centrosa','Accounting venue remains the source venue');
select is((select valid_venue_keys from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),array['cafe-des-stagiaires','ha-do-centrosa'],'Both selected venues saved');
select lives_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,'86000000-0000-4000-8000-000000000021',100000,'Both venues',90,array['cafe-des-stagiaires','ha-do-centrosa','ha-do-centrosa'])$q$,'Reordered duplicate selection retries exactly once');
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,'86000000-0000-4000-8000-000000000021',100000,'Both venues',90,array['ha-do-centrosa'])$q$,'P0001','Request reference already used.','Retry cannot change venue validity');
select is((select total from public.staff_orders where id='86000000-0000-4000-8000-000000000011'),200000,'Retry does not convert money twice');
reset role;
select set_config('test.multi_venue_code',(select code from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),true);
select ok(not(public.payment_voucher_quote(current_setting('test.multi_venue_code'),'ha-do-centrosa') ? 'error'),'Quote accepts Ha Do');
select ok(not(public.payment_voucher_quote(current_setting('test.multi_venue_code'),'cafe-des-stagiaires') ? 'error'),'Quote accepts Thao Dien');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',current_setting('test.venue_staff_login'),'aal','aal1')::text,true);
select set_config('request.headers','{"x-vrena-operator-session":"multi-venue-td-token"}',true);
set local role authenticated;
select is((select count(*)::int from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),0,'Destination staff cannot browse source-venue bearer codes');
select is((select count(*)::int from public.staff_orders where id='86000000-0000-4000-8000-000000000011'),0,'Destination staff cannot read source order');
select lives_ok($q$select public.staff_redeem_payment_voucher('86000000-0000-4000-8000-000000000012',current_setting('test.multi_venue_code'),'86000000-0000-4000-8000-000000000022',10000)$q$,'Destination-only staff can redeem a presented valid code');
select ok(not((public.staff_redeem_payment_voucher('86000000-0000-4000-8000-000000000012',current_setting('test.multi_venue_code'),'86000000-0000-4000-8000-000000000022',10000)->'voucher') ? 'source_order_id'),'Redemption response does not disclose source order');
reset role;
select is((select balance from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),90000,'Both venues share one balance');
update public.payment_vouchers set valid_venue_keys=array['ha-do-centrosa'] where id='86000000-0000-4000-8000-000000000021';
select ok(public.payment_voucher_quote(current_setting('test.multi_venue_code'),'cafe-des-stagiaires') ? 'error','Unselected venue cannot quote credit');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"86000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select throws_ok($q$select public.staff_redeem_payment_voucher('86000000-0000-4000-8000-000000000012',current_setting('test.multi_venue_code'),gen_random_uuid(),1000)$q$,'P0001','Voucher not found or location access denied.','Even admin cannot redeem outside voucher validity');
update public.payment_vouchers set valid_venue_keys=array['cafe-des-stagiaires','ha-do-centrosa'] where id='86000000-0000-4000-8000-000000000021';
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select lives_ok($q$select public.book_ticket_with_payment_voucher('create_cafe_ticket_booking_request',jsonb_build_object('p_ticket_type','individual','p_date',current_date+146,'p_start_time','16:00','p_duration_minutes',30,'p_player_count',1,'p_arena_count',1,'p_game_options',jsonb_build_array('city-z'),'p_guest_phone','0987654096','p_guest_name','Multi venue guest'),current_setting('test.multi_venue_code'),'86000000-0000-4000-8000-000000000023')$q$,'Online checkout can use Ha Do-issued credit at selected Thao Dien');
reset role;
select is((select balance from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),0,'Online redemption spends shared remaining balance once');
select * from finish();
rollback;
